-- Kompozit Group (ООО «Композит Групп», Душанбе) -- demo database of a composite materials manufacturer in Tajikistan
-- FICTIONAL DATA generated for BI dashboard demos. Currencies: TJS (somoni) and USD. Period: 2023-01-01 .. 2026-09-30.
-- No public information about the company was found: the profile (pultruded GFRP rebar and profiles, filament-wound pipes and tanks,
-- panels, SMC parts, transport components and own composite compounds; plants in Dushanbe and Vahdat, warehouse in Khujand) is an assumption;
-- customers, vendors, people, FX rates, VAT rates and all numbers are invented.
-- Schema is intentionally different from fatir_agro.sql and khimus.sql: project-style flow (opportunity -> quote -> contract -> work order -> dispatch),
-- multi-currency contracts and invoices, routing operations, tooling, cure cycles, raw-material lots (FIFO), lab tests, NCR, claims,
-- downtime and maintenance, energy meters, HSE incidents, cost centers, budget and sales plan. Tables are prefixed by domain (crm_, sls_, mfg_, scm_, qa_ ...).
-- Safe to import into an empty MySQL 8 schema.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';


DROP TABLE IF EXISTS `fin_sales_plan`;
DROP TABLE IF EXISTS `fin_budget`;
DROP TABLE IF EXISTS `fin_expense`;
DROP TABLE IF EXISTS `hse_incident`;
DROP TABLE IF EXISTS `ops_energy_reading`;
DROP TABLE IF EXISTS `mfg_maintenance`;
DROP TABLE IF EXISTS `mfg_downtime`;
DROP TABLE IF EXISTS `qa_ncr`;
DROP TABLE IF EXISTS `sls_claim`;
DROP TABLE IF EXISTS `sls_dispatch_item`;
DROP TABLE IF EXISTS `sls_dispatch`;
DROP TABLE IF EXISTS `qa_test`;
DROP TABLE IF EXISTS `qa_test_method`;
DROP TABLE IF EXISTS `scm_stock_snapshot`;
DROP TABLE IF EXISTS `mfg_material_issue`;
DROP TABLE IF EXISTS `scm_receipt`;
DROP TABLE IF EXISTS `scm_po_item`;
DROP TABLE IF EXISTS `scm_po`;
DROP TABLE IF EXISTS `mfg_scrap_log`;
DROP TABLE IF EXISTS `mfg_cure_cycle`;
DROP TABLE IF EXISTS `mfg_wo_operation`;
DROP TABLE IF EXISTS `mfg_work_order`;
DROP TABLE IF EXISTS `sls_payment`;
DROP TABLE IF EXISTS `sls_invoice`;
DROP TABLE IF EXISTS `sls_contract_item`;
DROP TABLE IF EXISTS `sls_contract`;
DROP TABLE IF EXISTS `crm_quote_item`;
DROP TABLE IF EXISTS `crm_quote`;
DROP TABLE IF EXISTS `crm_opportunity`;
DROP TABLE IF EXISTS `crm_account`;
DROP TABLE IF EXISTS `crm_industry`;
DROP TABLE IF EXISTS `mfg_tooling`;
DROP TABLE IF EXISTS `mfg_workcenter`;
DROP TABLE IF EXISTS `mfg_bom`;
DROP TABLE IF EXISTS `scm_material`;
DROP TABLE IF EXISTS `scm_vendor`;
DROP TABLE IF EXISTS `scm_material_group`;
DROP TABLE IF EXISTS `cat_price_history`;
DROP TABLE IF EXISTS `cat_product`;
DROP TABLE IF EXISTS `mfg_process`;
DROP TABLE IF EXISTS `cat_family`;
DROP TABLE IF EXISTS `fin_fx_rate`;
DROP TABLE IF EXISTS `hr_timesheet`;
DROP TABLE IF EXISTS `hr_employee`;
DROP TABLE IF EXISTS `hr_department`;
DROP TABLE IF EXISTS `fin_cost_center`;
DROP TABLE IF EXISTS `core_site`;

CREATE TABLE `core_site` (
    `site_id` TINYINT UNSIGNED NOT NULL,
    `site_code` VARCHAR(10) NOT NULL,
    `site_name` VARCHAR(120) NOT NULL,
    `site_type` ENUM('plant','warehouse','office') NOT NULL,
    `city` VARCHAR(40) NOT NULL,
    `address` VARCHAR(120) NOT NULL,
    `latitude` DECIMAL(9,6) NOT NULL,
    `longitude` DECIMAL(9,6) NOT NULL,
    `area_m2` INT UNSIGNED NOT NULL,
    `opened_on` DATE NOT NULL,
    PRIMARY KEY (`site_id`),
    UNIQUE KEY `uq_site_code` (`site_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Площадки компании';

CREATE TABLE `fin_cost_center` (
    `cc_id` TINYINT UNSIGNED NOT NULL,
    `cc_code` VARCHAR(10) NOT NULL,
    `cc_name` VARCHAR(80) NOT NULL,
    `site_id` TINYINT UNSIGNED NOT NULL,
    `owner_emp_id` SMALLINT UNSIGNED NULL,
    PRIMARY KEY (`cc_id`),
    UNIQUE KEY `uq_cc_code` (`cc_code`),
    CONSTRAINT `fk_cc_site` FOREIGN KEY (`site_id`) REFERENCES `core_site` (`site_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Центры затрат';

CREATE TABLE `hr_department` (
    `dept_id` TINYINT UNSIGNED NOT NULL,
    `dept_code` VARCHAR(8) NOT NULL,
    `dept_name` VARCHAR(80) NOT NULL,
    `cc_id` TINYINT UNSIGNED NOT NULL,
    PRIMARY KEY (`dept_id`),
    UNIQUE KEY `uq_dept_code` (`dept_code`),
    CONSTRAINT `fk_dept_cc` FOREIGN KEY (`cc_id`) REFERENCES `fin_cost_center` (`cc_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Подразделения';

CREATE TABLE `hr_employee` (
    `emp_id` SMALLINT UNSIGNED NOT NULL,
    `personnel_no` VARCHAR(8) NOT NULL,
    `full_name` VARCHAR(80) NOT NULL,
    `gender` ENUM('M','F') NOT NULL,
    `birth_date` DATE NOT NULL,
    `dept_id` TINYINT UNSIGNED NOT NULL,
    `site_id` TINYINT UNSIGNED NOT NULL,
    `job_title` VARCHAR(80) NOT NULL,
    `staff_category` ENUM('executive','manager','engineer','worker') NOT NULL,
    `shift_pattern` ENUM('office','day','two_shift') NOT NULL,
    `manager_id` SMALLINT UNSIGNED NULL,
    `education` ENUM('secondary','vocational','higher') NOT NULL,
    `hired_on` DATE NOT NULL,
    `terminated_on` DATE NULL,
    `termination_reason` ENUM('resigned','dismissed','redundancy','relocation') NULL,
    `base_salary_tjs` DECIMAL(10,2) NOT NULL,
    `work_email` VARCHAR(60) NOT NULL,
    `phone` VARCHAR(20) NOT NULL,
    PRIMARY KEY (`emp_id`),
    UNIQUE KEY `uq_emp_personnel_no` (`personnel_no`),
    KEY `ix_emp_dept` (`dept_id`),
    KEY `ix_emp_site` (`site_id`),
    CONSTRAINT `fk_emp_dept` FOREIGN KEY (`dept_id`) REFERENCES `hr_department` (`dept_id`),
    CONSTRAINT `fk_emp_site` FOREIGN KEY (`site_id`) REFERENCES `core_site` (`site_id`),
    CONSTRAINT `fk_emp_manager` FOREIGN KEY (`manager_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Сотрудники';

CREATE TABLE `hr_timesheet` (
    `period_month` DATE NOT NULL,
    `emp_id` SMALLINT UNSIGNED NOT NULL,
    `work_days` TINYINT UNSIGNED NOT NULL,
    `hours_worked` DECIMAL(6,1) NOT NULL,
    `overtime_hours` DECIMAL(5,1) NOT NULL,
    `sick_days` TINYINT UNSIGNED NOT NULL,
    `vacation_days` TINYINT UNSIGNED NOT NULL,
    `gross_pay_tjs` DECIMAL(10,2) NOT NULL,
    `bonus_tjs` DECIMAL(10,2) NOT NULL,
    PRIMARY KEY (`period_month`, `emp_id`),
    KEY `ix_ts_emp` (`emp_id`),
    CONSTRAINT `fk_ts_emp` FOREIGN KEY (`emp_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Табель и начисления по месяцам (период = первое число месяца)';

CREATE TABLE `fin_fx_rate` (
    `rate_date` DATE NOT NULL,
    `currency` CHAR(3) NOT NULL,
    `rate_to_tjs` DECIMAL(12,6) NOT NULL,
    PRIMARY KEY (`rate_date`, `currency`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Недельные курсы валют к сомони за 1 единицу валюты';

CREATE TABLE `cat_family` (
    `family_id` TINYINT UNSIGNED NOT NULL,
    `family_code` VARCHAR(6) NOT NULL,
    `family_name` VARCHAR(80) NOT NULL,
    `market_segment` ENUM('construction','infrastructure','industrial','transport','chemicals') NOT NULL,
    `typical_lead_days` SMALLINT UNSIGNED NOT NULL,
    `description` VARCHAR(255) NOT NULL,
    PRIMARY KEY (`family_id`),
    UNIQUE KEY `uq_family_code` (`family_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Семейства продукции';

CREATE TABLE `mfg_process` (
    `process_id` TINYINT UNSIGNED NOT NULL,
    `process_code` VARCHAR(6) NOT NULL,
    `process_name` VARCHAR(80) NOT NULL,
    `is_continuous` TINYINT(1) NOT NULL,
    `needs_tooling` TINYINT(1) NOT NULL,
    `default_site_id` TINYINT UNSIGNED NOT NULL,
    `route` VARCHAR(120) NOT NULL,
    PRIMARY KEY (`process_id`),
    UNIQUE KEY `uq_process_code` (`process_code`),
    CONSTRAINT `fk_process_site` FOREIGN KEY (`default_site_id`) REFERENCES `core_site` (`site_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Технологические процессы и маршруты';

CREATE TABLE `cat_product` (
    `product_id` SMALLINT UNSIGNED NOT NULL,
    `sku` VARCHAR(16) NOT NULL,
    `family_id` TINYINT UNSIGNED NOT NULL,
    `process_id` TINYINT UNSIGNED NOT NULL,
    `product_name` VARCHAR(160) NOT NULL,
    `specification` VARCHAR(160) NOT NULL,
    `uom` ENUM('m','m2','pcs','kg') NOT NULL,
    `weight_kg_per_uom` DECIMAL(9,3) NOT NULL,
    `standard_ref` VARCHAR(40) NULL,
    `std_cost_tjs` DECIMAL(12,2) NOT NULL,
    `list_price_usd` DECIMAL(12,3) NOT NULL,
    `launched_on` DATE NOT NULL,
    `discontinued_on` DATE NULL,
    PRIMARY KEY (`product_id`),
    UNIQUE KEY `uq_product_sku` (`sku`),
    KEY `ix_product_family` (`family_id`),
    CONSTRAINT `fk_product_family` FOREIGN KEY (`family_id`) REFERENCES `cat_family` (`family_id`),
    CONSTRAINT `fk_product_process` FOREIGN KEY (`process_id`) REFERENCES `mfg_process` (`process_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Номенклатура готовой продукции';

CREATE TABLE `cat_price_history` (
    `product_id` SMALLINT UNSIGNED NOT NULL,
    `valid_from` DATE NOT NULL,
    `list_price_usd` DECIMAL(12,3) NOT NULL,
    PRIMARY KEY (`product_id`, `valid_from`),
    CONSTRAINT `fk_ph_product` FOREIGN KEY (`product_id`) REFERENCES `cat_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='История прайс-листа (USD, без НДС)';

CREATE TABLE `scm_material_group` (
    `group_id` TINYINT UNSIGNED NOT NULL,
    `group_code` VARCHAR(4) NOT NULL,
    `group_name` VARCHAR(60) NOT NULL,
    PRIMARY KEY (`group_id`),
    UNIQUE KEY `uq_mgroup_code` (`group_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Группы сырья и материалов';

CREATE TABLE `scm_vendor` (
    `vendor_id` SMALLINT UNSIGNED NOT NULL,
    `vendor_name` VARCHAR(120) NOT NULL,
    `country` VARCHAR(40) NOT NULL,
    `vendor_type` ENUM('manufacturer','distributor','local_trader') NOT NULL,
    `currency` CHAR(3) NOT NULL,
    `incoterms` ENUM('EXW','FCA','CIF','DAP','DDP') NOT NULL,
    `lead_time_days` SMALLINT UNSIGNED NOT NULL,
    `payment_terms_days` SMALLINT UNSIGNED NOT NULL,
    `quality_rating` DECIMAL(3,1) NOT NULL,
    `onboarded_on` DATE NOT NULL,
    `is_active` TINYINT(1) NOT NULL,
    PRIMARY KEY (`vendor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Поставщики сырья и услуг';

CREATE TABLE `scm_material` (
    `material_id` SMALLINT UNSIGNED NOT NULL,
    `material_code` VARCHAR(10) NOT NULL,
    `group_id` TINYINT UNSIGNED NOT NULL,
    `material_name` VARCHAR(150) NOT NULL,
    `uom` ENUM('kg','m2','m','pcs') NOT NULL,
    `std_price_usd` DECIMAL(10,3) NOT NULL,
    `shelf_life_days` SMALLINT UNSIGNED NULL,
    `storage_class` ENUM('ambient','cool','flammable_store') NOT NULL,
    `purchase_lot_size` DECIMAL(10,1) NOT NULL,
    `preferred_vendor_id` SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`material_id`),
    UNIQUE KEY `uq_material_code` (`material_code`),
    KEY `ix_material_group` (`group_id`),
    CONSTRAINT `fk_material_group` FOREIGN KEY (`group_id`) REFERENCES `scm_material_group` (`group_id`),
    CONSTRAINT `fk_material_vendor` FOREIGN KEY (`preferred_vendor_id`) REFERENCES `scm_vendor` (`vendor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Номенклатура сырья и материалов';

CREATE TABLE `mfg_bom` (
    `bom_id` INT UNSIGNED NOT NULL,
    `product_id` SMALLINT UNSIGNED NOT NULL,
    `material_id` SMALLINT UNSIGNED NOT NULL,
    `qty_per_uom` DECIMAL(12,5) NOT NULL,
    `scrap_pct` DECIMAL(4,1) NOT NULL,
    `valid_from` DATE NOT NULL,
    `valid_to` DATE NULL,
    PRIMARY KEY (`bom_id`),
    KEY `ix_bom_product` (`product_id`),
    KEY `ix_bom_material` (`material_id`),
    CONSTRAINT `fk_bom_product` FOREIGN KEY (`product_id`) REFERENCES `cat_product` (`product_id`),
    CONSTRAINT `fk_bom_material` FOREIGN KEY (`material_id`) REFERENCES `scm_material` (`material_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Спецификации: расход материала на единицу продукции (версии по датам)';

CREATE TABLE `mfg_workcenter` (
    `wc_id` TINYINT UNSIGNED NOT NULL,
    `wc_code` VARCHAR(10) NOT NULL,
    `site_id` TINYINT UNSIGNED NOT NULL,
    `wc_name` VARCHAR(80) NOT NULL,
    `wc_type` ENUM('prep_table','pultrusion_line','winder','layup_bay','infusion_bay','smc_press','rtm_press','mixer','oven','cnc_router','saw','qc_bench','pack_line') NOT NULL,
    `rated_kg_per_hour` DECIMAL(8,1) NULL,
    `power_kw` DECIMAL(7,1) NOT NULL,
    `commissioned_on` DATE NOT NULL,
    `wc_status` ENUM('active','under_repair','decommissioned') NOT NULL,
    PRIMARY KEY (`wc_id`),
    UNIQUE KEY `uq_wc_code` (`wc_code`),
    KEY `ix_wc_site` (`site_id`),
    CONSTRAINT `fk_wc_site` FOREIGN KEY (`site_id`) REFERENCES `core_site` (`site_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Рабочие центры (оборудование)';

CREATE TABLE `mfg_tooling` (
    `tooling_id` SMALLINT UNSIGNED NOT NULL,
    `tooling_code` VARCHAR(12) NOT NULL,
    `tooling_type` ENUM('die','mandrel','mold','press_tool') NOT NULL,
    `product_id` SMALLINT UNSIGNED NOT NULL,
    `material` ENUM('steel','chrome_steel','aluminium','fiberglass_epoxy') NOT NULL,
    `site_id` TINYINT UNSIGNED NOT NULL,
    `cost_usd` DECIMAL(10,2) NOT NULL,
    `commissioned_on` DATE NOT NULL,
    `runs_count` INT UNSIGNED NOT NULL,
    `refurbish_interval_runs` SMALLINT UNSIGNED NOT NULL,
    `last_refurbished_on` DATE NULL,
    `tooling_status` ENUM('in_service','refurbishment','retired') NOT NULL,
    PRIMARY KEY (`tooling_id`),
    UNIQUE KEY `uq_tooling_code` (`tooling_code`),
    KEY `ix_tooling_product` (`product_id`),
    CONSTRAINT `fk_tooling_product` FOREIGN KEY (`product_id`) REFERENCES `cat_product` (`product_id`),
    CONSTRAINT `fk_tooling_site` FOREIGN KEY (`site_id`) REFERENCES `core_site` (`site_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Оснастка: фильеры, оправки, формы';

CREATE TABLE `crm_industry` (
    `industry_id` TINYINT UNSIGNED NOT NULL,
    `industry_code` VARCHAR(8) NOT NULL,
    `industry_name` VARCHAR(80) NOT NULL,
    PRIMARY KEY (`industry_id`),
    UNIQUE KEY `uq_industry_code` (`industry_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Отрасли клиентов';

CREATE TABLE `crm_account` (
    `account_id` SMALLINT UNSIGNED NOT NULL,
    `account_no` VARCHAR(10) NOT NULL,
    `account_name` VARCHAR(150) NOT NULL,
    `industry_id` TINYINT UNSIGNED NOT NULL,
    `sales_channel` ENUM('direct','distributor','tender','export') NOT NULL,
    `size_class` ENUM('small','medium','large') NOT NULL,
    `country` VARCHAR(40) NOT NULL,
    `city` VARCHAR(40) NOT NULL,
    `address` VARCHAR(120) NOT NULL,
    `latitude` DECIMAL(9,6) NOT NULL,
    `longitude` DECIMAL(9,6) NOT NULL,
    `tax_id` VARCHAR(12) NOT NULL,
    `contact_person` VARCHAR(80) NOT NULL,
    `contact_phone` VARCHAR(20) NOT NULL,
    `account_manager_id` SMALLINT UNSIGNED NOT NULL,
    `created_on` DATE NOT NULL,
    `credit_limit_usd` DECIMAL(12,2) NOT NULL,
    `payment_terms_days` SMALLINT UNSIGNED NOT NULL,
    `account_status` ENUM('active','dormant','blocked') NOT NULL,
    PRIMARY KEY (`account_id`),
    UNIQUE KEY `uq_account_no` (`account_no`),
    KEY `ix_account_industry` (`industry_id`),
    KEY `ix_account_manager` (`account_manager_id`),
    CONSTRAINT `fk_account_industry` FOREIGN KEY (`industry_id`) REFERENCES `crm_industry` (`industry_id`),
    CONSTRAINT `fk_account_manager` FOREIGN KEY (`account_manager_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Клиенты (юрлица)';

CREATE TABLE `crm_opportunity` (
    `opp_id` INT UNSIGNED NOT NULL,
    `account_id` SMALLINT UNSIGNED NOT NULL,
    `owner_emp_id` SMALLINT UNSIGNED NOT NULL,
    `opp_title` VARCHAR(160) NOT NULL,
    `primary_family_id` TINYINT UNSIGNED NOT NULL,
    `lead_source` ENUM('tender','inbound','referral','exhibition','cold_call','repeat') NOT NULL,
    `stage` ENUM('open','won','lost') NOT NULL,
    `created_on` DATE NOT NULL,
    `closed_on` DATE NULL,
    `expected_value_usd` DECIMAL(12,2) NOT NULL,
    `loss_reason` ENUM('price','lead_time','import_competitor','specs_not_met','budget_cut','no_response') NULL,
    PRIMARY KEY (`opp_id`),
    KEY `ix_opp_account` (`account_id`),
    KEY `ix_opp_owner` (`owner_emp_id`),
    KEY `ix_opp_created` (`created_on`),
    CONSTRAINT `fk_opp_account` FOREIGN KEY (`account_id`) REFERENCES `crm_account` (`account_id`),
    CONSTRAINT `fk_opp_owner` FOREIGN KEY (`owner_emp_id`) REFERENCES `hr_employee` (`emp_id`),
    CONSTRAINT `fk_opp_family` FOREIGN KEY (`primary_family_id`) REFERENCES `cat_family` (`family_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Воронка продаж: сделки';

CREATE TABLE `crm_quote` (
    `quote_id` INT UNSIGNED NOT NULL,
    `quote_no` VARCHAR(16) NOT NULL,
    `opp_id` INT UNSIGNED NOT NULL,
    `account_id` SMALLINT UNSIGNED NOT NULL,
    `quote_date` DATE NOT NULL,
    `valid_until` DATE NOT NULL,
    `currency` CHAR(3) NOT NULL,
    `fx_rate_to_tjs` DECIMAL(12,6) NOT NULL,
    `quote_status` ENUM('draft','sent','accepted','rejected','expired') NOT NULL,
    `total_net_amount` DECIMAL(14,2) NOT NULL,
    `prepared_by_id` SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`quote_id`),
    UNIQUE KEY `uq_quote_no` (`quote_no`),
    KEY `ix_quote_opp` (`opp_id`),
    KEY `ix_quote_date` (`quote_date`),
    CONSTRAINT `fk_quote_opp` FOREIGN KEY (`opp_id`) REFERENCES `crm_opportunity` (`opp_id`),
    CONSTRAINT `fk_quote_account` FOREIGN KEY (`account_id`) REFERENCES `crm_account` (`account_id`),
    CONSTRAINT `fk_quote_author` FOREIGN KEY (`prepared_by_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Коммерческие предложения';

CREATE TABLE `crm_quote_item` (
    `quote_id` INT UNSIGNED NOT NULL,
    `line_no` TINYINT UNSIGNED NOT NULL,
    `product_id` SMALLINT UNSIGNED NOT NULL,
    `qty` DECIMAL(12,2) NOT NULL,
    `unit_price` DECIMAL(12,3) NOT NULL,
    `discount_pct` DECIMAL(4,1) NOT NULL,
    PRIMARY KEY (`quote_id`, `line_no`),
    KEY `ix_qitem_product` (`product_id`),
    CONSTRAINT `fk_qitem_quote` FOREIGN KEY (`quote_id`) REFERENCES `crm_quote` (`quote_id`),
    CONSTRAINT `fk_qitem_product` FOREIGN KEY (`product_id`) REFERENCES `cat_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Строки коммерческих предложений';

CREATE TABLE `sls_contract` (
    `contract_id` INT UNSIGNED NOT NULL,
    `contract_no` VARCHAR(16) NOT NULL,
    `quote_id` INT UNSIGNED NOT NULL,
    `account_id` SMALLINT UNSIGNED NOT NULL,
    `signed_on` DATE NOT NULL,
    `delivery_deadline` DATE NOT NULL,
    `currency` CHAR(3) NOT NULL,
    `fx_rate_to_tjs` DECIMAL(12,6) NOT NULL,
    `incoterms` ENUM('EXW','FCA','DAP','CPT') NOT NULL,
    `delivery_city` VARCHAR(40) NOT NULL,
    `payment_scheme` ENUM('prepay100','advance30','advance50','net30','net60') NOT NULL,
    `contract_status` ENUM('in_production','delivered','completed','cancelled') NOT NULL,
    `sales_emp_id` SMALLINT UNSIGNED NOT NULL,
    `total_net_amount` DECIMAL(14,2) NOT NULL,
    `total_net_amount_tjs` DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (`contract_id`),
    UNIQUE KEY `uq_contract_no` (`contract_no`),
    KEY `ix_contract_account` (`account_id`),
    KEY `ix_contract_signed` (`signed_on`),
    CONSTRAINT `fk_contract_quote` FOREIGN KEY (`quote_id`) REFERENCES `crm_quote` (`quote_id`),
    CONSTRAINT `fk_contract_account` FOREIGN KEY (`account_id`) REFERENCES `crm_account` (`account_id`),
    CONSTRAINT `fk_contract_sales` FOREIGN KEY (`sales_emp_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Договоры поставки';

CREATE TABLE `sls_contract_item` (
    `contract_id` INT UNSIGNED NOT NULL,
    `line_no` TINYINT UNSIGNED NOT NULL,
    `product_id` SMALLINT UNSIGNED NOT NULL,
    `qty` DECIMAL(12,2) NOT NULL,
    `unit_price` DECIMAL(12,3) NOT NULL,
    `discount_pct` DECIMAL(4,1) NOT NULL,
    `line_net_amount` DECIMAL(14,2) NOT NULL,
    `required_date` DATE NOT NULL,
    `custom_spec` VARCHAR(200) NULL,
    PRIMARY KEY (`contract_id`, `line_no`),
    KEY `ix_citem_product` (`product_id`),
    CONSTRAINT `fk_citem_contract` FOREIGN KEY (`contract_id`) REFERENCES `sls_contract` (`contract_id`),
    CONSTRAINT `fk_citem_product` FOREIGN KEY (`product_id`) REFERENCES `cat_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Строки договоров (цена в валюте договора, без НДС)';

CREATE TABLE `sls_invoice` (
    `invoice_id` INT UNSIGNED NOT NULL,
    `invoice_no` VARCHAR(16) NOT NULL,
    `contract_id` INT UNSIGNED NOT NULL,
    `invoice_kind` ENUM('advance','interim','final') NOT NULL,
    `issued_on` DATE NOT NULL,
    `due_on` DATE NOT NULL,
    `currency` CHAR(3) NOT NULL,
    `net_amount` DECIMAL(14,2) NOT NULL,
    `vat_rate_pct` DECIMAL(4,1) NOT NULL,
    `vat_amount` DECIMAL(14,2) NOT NULL,
    `gross_amount` DECIMAL(14,2) NOT NULL,
    `invoice_status` ENUM('open','partial','paid','overdue') NOT NULL,
    PRIMARY KEY (`invoice_id`),
    UNIQUE KEY `uq_invoice_no` (`invoice_no`),
    KEY `ix_invoice_contract` (`contract_id`),
    KEY `ix_invoice_issued` (`issued_on`),
    CONSTRAINT `fk_invoice_contract` FOREIGN KEY (`contract_id`) REFERENCES `sls_contract` (`contract_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Счета на оплату по договорам';

CREATE TABLE `sls_payment` (
    `payment_id` INT UNSIGNED NOT NULL,
    `invoice_id` INT UNSIGNED NOT NULL,
    `paid_on` DATE NOT NULL,
    `amount` DECIMAL(14,2) NOT NULL,
    `fx_rate_to_tjs` DECIMAL(12,6) NOT NULL,
    `payment_method` ENUM('bank_transfer','cash','letter_of_credit','offset') NOT NULL,
    `bank_ref` VARCHAR(20) NOT NULL,
    PRIMARY KEY (`payment_id`),
    KEY `ix_payment_invoice` (`invoice_id`),
    KEY `ix_payment_paid` (`paid_on`),
    CONSTRAINT `fk_payment_invoice` FOREIGN KEY (`invoice_id`) REFERENCES `sls_invoice` (`invoice_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Поступления от клиентов';

CREATE TABLE `mfg_work_order` (
    `wo_id` INT UNSIGNED NOT NULL,
    `wo_no` VARCHAR(14) NOT NULL,
    `contract_id` INT UNSIGNED NOT NULL,
    `contract_line_no` TINYINT UNSIGNED NOT NULL,
    `product_id` SMALLINT UNSIGNED NOT NULL,
    `site_id` TINYINT UNSIGNED NOT NULL,
    `tooling_id` SMALLINT UNSIGNED NULL,
    `primary_wc_id` TINYINT UNSIGNED NOT NULL,
    `wo_status` ENUM('planned','in_progress','closed') NOT NULL,
    `priority` ENUM('normal','high','urgent') NOT NULL,
    `planned_qty` DECIMAL(12,2) NOT NULL,
    `good_qty` DECIMAL(12,2) NOT NULL,
    `scrap_qty` DECIMAL(12,2) NOT NULL,
    `released_at` DATETIME NOT NULL,
    `scheduled_start` DATETIME NOT NULL,
    `actual_start` DATETIME NULL,
    `actual_end` DATETIME NULL,
    `due_date` DATE NOT NULL,
    `planner_emp_id` SMALLINT UNSIGNED NOT NULL,
    `shift_lead_id` SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`wo_id`),
    UNIQUE KEY `uq_wo_no` (`wo_no`),
    KEY `ix_wo_contract` (`contract_id`, `contract_line_no`),
    KEY `ix_wo_product` (`product_id`),
    KEY `ix_wo_start` (`actual_start`),
    CONSTRAINT `fk_wo_contract_item` FOREIGN KEY (`contract_id`, `contract_line_no`) REFERENCES `sls_contract_item` (`contract_id`, `line_no`),
    CONSTRAINT `fk_wo_product` FOREIGN KEY (`product_id`) REFERENCES `cat_product` (`product_id`),
    CONSTRAINT `fk_wo_site` FOREIGN KEY (`site_id`) REFERENCES `core_site` (`site_id`),
    CONSTRAINT `fk_wo_tooling` FOREIGN KEY (`tooling_id`) REFERENCES `mfg_tooling` (`tooling_id`),
    CONSTRAINT `fk_wo_wc` FOREIGN KEY (`primary_wc_id`) REFERENCES `mfg_workcenter` (`wc_id`),
    CONSTRAINT `fk_wo_planner` FOREIGN KEY (`planner_emp_id`) REFERENCES `hr_employee` (`emp_id`),
    CONSTRAINT `fk_wo_lead` FOREIGN KEY (`shift_lead_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Производственные заказы (партии под строку договора)';

CREATE TABLE `mfg_wo_operation` (
    `op_id` INT UNSIGNED NOT NULL,
    `wo_id` INT UNSIGNED NOT NULL,
    `op_seq` TINYINT UNSIGNED NOT NULL,
    `op_code` ENUM('PREP','PULTRUDE','WIND','LAYUP','INFUSE','PRESS','INJECT','BLEND','CURE','DEMOLD','CUT','TRIM','QC','PACK') NOT NULL,
    `wc_id` TINYINT UNSIGNED NOT NULL,
    `operator_id` SMALLINT UNSIGNED NOT NULL,
    `started_at` DATETIME NOT NULL,
    `finished_at` DATETIME NULL,
    `setup_min` SMALLINT UNSIGNED NOT NULL,
    `run_min` INT UNSIGNED NOT NULL,
    `qty_in` DECIMAL(12,2) NOT NULL,
    `qty_good` DECIMAL(12,2) NOT NULL,
    `qty_scrap` DECIMAL(12,2) NOT NULL,
    PRIMARY KEY (`op_id`),
    KEY `ix_op_wo` (`wo_id`),
    KEY `ix_op_wc` (`wc_id`, `started_at`),
    CONSTRAINT `fk_op_wo` FOREIGN KEY (`wo_id`) REFERENCES `mfg_work_order` (`wo_id`),
    CONSTRAINT `fk_op_wc` FOREIGN KEY (`wc_id`) REFERENCES `mfg_workcenter` (`wc_id`),
    CONSTRAINT `fk_op_operator` FOREIGN KEY (`operator_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Операции маршрута производственного заказа';

CREATE TABLE `mfg_cure_cycle` (
    `cycle_id` INT UNSIGNED NOT NULL,
    `wo_id` INT UNSIGNED NOT NULL,
    `op_id` INT UNSIGNED NOT NULL,
    `wc_id` TINYINT UNSIGNED NOT NULL,
    `started_at` DATETIME NOT NULL,
    `duration_min` INT UNSIGNED NOT NULL,
    `target_temp_c` DECIMAL(5,1) NOT NULL,
    `peak_temp_c` DECIMAL(5,1) NOT NULL,
    `ramp_c_per_min` DECIMAL(4,2) NOT NULL,
    `energy_kwh` DECIMAL(9,1) NOT NULL,
    `cure_result` ENUM('ok','undercured','overcured') NOT NULL,
    PRIMARY KEY (`cycle_id`),
    KEY `ix_cure_wo` (`wo_id`),
    KEY `ix_cure_wc` (`wc_id`),
    CONSTRAINT `fk_cure_wo` FOREIGN KEY (`wo_id`) REFERENCES `mfg_work_order` (`wo_id`),
    CONSTRAINT `fk_cure_op` FOREIGN KEY (`op_id`) REFERENCES `mfg_wo_operation` (`op_id`),
    CONSTRAINT `fk_cure_wc` FOREIGN KEY (`wc_id`) REFERENCES `mfg_workcenter` (`wc_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Циклы отверждения в печах (термограммы в сводном виде)';

CREATE TABLE `mfg_scrap_log` (
    `scrap_id` INT UNSIGNED NOT NULL,
    `wo_id` INT UNSIGNED NOT NULL,
    `op_id` INT UNSIGNED NOT NULL,
    `scrap_date` DATE NOT NULL,
    `reason_code` VARCHAR(24) NOT NULL,
    `qty_scrap` DECIMAL(12,2) NOT NULL,
    `scrap_cost_tjs` DECIMAL(12,2) NOT NULL,
    `responsibility` ENUM('process','material','equipment','operator','design') NOT NULL,
    PRIMARY KEY (`scrap_id`),
    KEY `ix_scrap_wo` (`wo_id`),
    KEY `ix_scrap_date` (`scrap_date`),
    CONSTRAINT `fk_scrap_wo` FOREIGN KEY (`wo_id`) REFERENCES `mfg_work_order` (`wo_id`),
    CONSTRAINT `fk_scrap_op` FOREIGN KEY (`op_id`) REFERENCES `mfg_wo_operation` (`op_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Журнал брака по операциям';

CREATE TABLE `scm_po` (
    `po_id` INT UNSIGNED NOT NULL,
    `po_no` VARCHAR(14) NOT NULL,
    `vendor_id` SMALLINT UNSIGNED NOT NULL,
    `site_id` TINYINT UNSIGNED NOT NULL,
    `buyer_emp_id` SMALLINT UNSIGNED NOT NULL,
    `order_date` DATE NOT NULL,
    `expected_date` DATE NOT NULL,
    `currency` CHAR(3) NOT NULL,
    `fx_rate_to_tjs` DECIMAL(12,6) NOT NULL,
    `incoterms` ENUM('EXW','FCA','CIF','DAP','DDP') NOT NULL,
    `po_status` ENUM('open','partial','received','cancelled') NOT NULL,
    `freight_amount` DECIMAL(12,2) NOT NULL,
    `customs_duty_tjs` DECIMAL(12,2) NOT NULL,
    PRIMARY KEY (`po_id`),
    UNIQUE KEY `uq_po_no` (`po_no`),
    KEY `ix_po_vendor` (`vendor_id`),
    KEY `ix_po_order` (`order_date`),
    CONSTRAINT `fk_po_vendor` FOREIGN KEY (`vendor_id`) REFERENCES `scm_vendor` (`vendor_id`),
    CONSTRAINT `fk_po_site` FOREIGN KEY (`site_id`) REFERENCES `core_site` (`site_id`),
    CONSTRAINT `fk_po_buyer` FOREIGN KEY (`buyer_emp_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Заказы поставщикам';

CREATE TABLE `scm_po_item` (
    `po_item_id` INT UNSIGNED NOT NULL,
    `po_id` INT UNSIGNED NOT NULL,
    `line_no` TINYINT UNSIGNED NOT NULL,
    `material_id` SMALLINT UNSIGNED NOT NULL,
    `qty_ordered` DECIMAL(14,2) NOT NULL,
    `unit_price` DECIMAL(12,4) NOT NULL,
    `qty_received` DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (`po_item_id`),
    UNIQUE KEY `uq_po_line` (`po_id`, `line_no`),
    KEY `ix_poitem_material` (`material_id`),
    CONSTRAINT `fk_poitem_po` FOREIGN KEY (`po_id`) REFERENCES `scm_po` (`po_id`),
    CONSTRAINT `fk_poitem_material` FOREIGN KEY (`material_id`) REFERENCES `scm_material` (`material_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Строки заказов поставщикам (цена в валюте заказа за единицу материала)';

CREATE TABLE `scm_receipt` (
    `receipt_id` INT UNSIGNED NOT NULL,
    `receipt_no` VARCHAR(14) NOT NULL,
    `po_item_id` INT UNSIGNED NULL,
    `material_id` SMALLINT UNSIGNED NOT NULL,
    `site_id` TINYINT UNSIGNED NOT NULL,
    `received_on` DATE NOT NULL,
    `lot_no` VARCHAR(20) NOT NULL,
    `qty_received` DECIMAL(14,2) NOT NULL,
    `qty_accepted` DECIMAL(14,2) NOT NULL,
    `unit_cost_tjs` DECIMAL(12,4) NOT NULL,
    `expiry_date` DATE NULL,
    `qc_status` ENUM('released','quarantine','rejected') NOT NULL,
    `received_by_id` SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`receipt_id`),
    UNIQUE KEY `uq_receipt_no` (`receipt_no`),
    KEY `ix_receipt_material` (`material_id`, `received_on`),
    KEY `ix_receipt_poitem` (`po_item_id`),
    CONSTRAINT `fk_receipt_poitem` FOREIGN KEY (`po_item_id`) REFERENCES `scm_po_item` (`po_item_id`),
    CONSTRAINT `fk_receipt_material` FOREIGN KEY (`material_id`) REFERENCES `scm_material` (`material_id`),
    CONSTRAINT `fk_receipt_site` FOREIGN KEY (`site_id`) REFERENCES `core_site` (`site_id`),
    CONSTRAINT `fk_receipt_by` FOREIGN KEY (`received_by_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Приёмка партий сырья (po_item_id пуст у входящих остатков на 01.01.2023)';

CREATE TABLE `mfg_material_issue` (
    `issue_id` INT UNSIGNED NOT NULL,
    `wo_id` INT UNSIGNED NOT NULL,
    `material_id` SMALLINT UNSIGNED NOT NULL,
    `receipt_id` INT UNSIGNED NOT NULL,
    `issued_on` DATE NOT NULL,
    `qty_planned` DECIMAL(14,3) NOT NULL,
    `qty_issued` DECIMAL(14,3) NOT NULL,
    `unit_cost_tjs` DECIMAL(12,4) NOT NULL,
    PRIMARY KEY (`issue_id`),
    KEY `ix_issue_wo` (`wo_id`),
    KEY `ix_issue_material` (`material_id`, `issued_on`),
    KEY `ix_issue_receipt` (`receipt_id`),
    CONSTRAINT `fk_issue_wo` FOREIGN KEY (`wo_id`) REFERENCES `mfg_work_order` (`wo_id`),
    CONSTRAINT `fk_issue_material` FOREIGN KEY (`material_id`) REFERENCES `scm_material` (`material_id`),
    CONSTRAINT `fk_issue_receipt` FOREIGN KEY (`receipt_id`) REFERENCES `scm_receipt` (`receipt_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Списание материалов в производство по партиям (FIFO)';

CREATE TABLE `scm_stock_snapshot` (
    `period_end` DATE NOT NULL,
    `site_id` TINYINT UNSIGNED NOT NULL,
    `material_id` SMALLINT UNSIGNED NOT NULL,
    `qty_on_hand` DECIMAL(14,2) NOT NULL,
    `avg_unit_cost_tjs` DECIMAL(12,4) NOT NULL,
    `days_of_cover` SMALLINT UNSIGNED NULL,
    PRIMARY KEY (`period_end`, `site_id`, `material_id`),
    KEY `ix_snap_material` (`material_id`),
    CONSTRAINT `fk_snap_site` FOREIGN KEY (`site_id`) REFERENCES `core_site` (`site_id`),
    CONSTRAINT `fk_snap_material` FOREIGN KEY (`material_id`) REFERENCES `scm_material` (`material_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Остатки сырья на конец месяца';

CREATE TABLE `qa_test_method` (
    `method_id` TINYINT UNSIGNED NOT NULL,
    `method_code` VARCHAR(10) NOT NULL,
    `method_name` VARCHAR(100) NOT NULL,
    `standard_ref` VARCHAR(40) NOT NULL,
    `unit` VARCHAR(12) NOT NULL,
    `applies_to` ENUM('finished_goods','incoming') NOT NULL,
    PRIMARY KEY (`method_id`),
    UNIQUE KEY `uq_method_code` (`method_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Методы лабораторных испытаний';

CREATE TABLE `qa_test` (
    `test_id` INT UNSIGNED NOT NULL,
    `test_no` VARCHAR(12) NOT NULL,
    `test_scope` ENUM('batch','incoming') NOT NULL,
    `wo_id` INT UNSIGNED NULL,
    `receipt_id` INT UNSIGNED NULL,
    `method_id` TINYINT UNSIGNED NOT NULL,
    `tested_on` DATE NOT NULL,
    `tester_id` SMALLINT UNSIGNED NOT NULL,
    `measured_value` DECIMAL(12,3) NOT NULL,
    `spec_min` DECIMAL(12,3) NULL,
    `spec_max` DECIMAL(12,3) NULL,
    `test_result` ENUM('pass','fail') NOT NULL,
    `is_retest` TINYINT(1) NOT NULL,
    PRIMARY KEY (`test_id`),
    UNIQUE KEY `uq_test_no` (`test_no`),
    KEY `ix_test_wo` (`wo_id`),
    KEY `ix_test_receipt` (`receipt_id`),
    KEY `ix_test_date` (`tested_on`),
    CONSTRAINT `fk_test_wo` FOREIGN KEY (`wo_id`) REFERENCES `mfg_work_order` (`wo_id`),
    CONSTRAINT `fk_test_receipt` FOREIGN KEY (`receipt_id`) REFERENCES `scm_receipt` (`receipt_id`),
    CONSTRAINT `fk_test_method` FOREIGN KEY (`method_id`) REFERENCES `qa_test_method` (`method_id`),
    CONSTRAINT `fk_test_tester` FOREIGN KEY (`tester_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Результаты испытаний партий и входного контроля';

CREATE TABLE `sls_dispatch` (
    `dispatch_id` INT UNSIGNED NOT NULL,
    `dispatch_no` VARCHAR(14) NOT NULL,
    `contract_id` INT UNSIGNED NOT NULL,
    `from_site_id` TINYINT UNSIGNED NOT NULL,
    `shipped_on` DATE NOT NULL,
    `delivered_on` DATE NULL,
    `carrier_type` ENUM('own_truck','hired_truck','rail','container') NOT NULL,
    `vehicle_plate` VARCHAR(12) NULL,
    `destination_city` VARCHAR(40) NOT NULL,
    `destination_country` VARCHAR(40) NOT NULL,
    `distance_km` INT UNSIGNED NOT NULL,
    `gross_weight_kg` DECIMAL(12,1) NOT NULL,
    `freight_cost_tjs` DECIMAL(12,2) NOT NULL,
    `dispatch_status` ENUM('in_transit','delivered','returned') NOT NULL,
    PRIMARY KEY (`dispatch_id`),
    UNIQUE KEY `uq_dispatch_no` (`dispatch_no`),
    KEY `ix_dispatch_contract` (`contract_id`),
    KEY `ix_dispatch_shipped` (`shipped_on`),
    CONSTRAINT `fk_dispatch_contract` FOREIGN KEY (`contract_id`) REFERENCES `sls_contract` (`contract_id`),
    CONSTRAINT `fk_dispatch_site` FOREIGN KEY (`from_site_id`) REFERENCES `core_site` (`site_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Отгрузки клиентам';

CREATE TABLE `sls_dispatch_item` (
    `dispatch_id` INT UNSIGNED NOT NULL,
    `line_no` TINYINT UNSIGNED NOT NULL,
    `contract_line_no` TINYINT UNSIGNED NOT NULL,
    `wo_id` INT UNSIGNED NOT NULL,
    `qty_shipped` DECIMAL(12,2) NOT NULL,
    PRIMARY KEY (`dispatch_id`, `line_no`),
    KEY `ix_ditem_wo` (`wo_id`),
    CONSTRAINT `fk_ditem_dispatch` FOREIGN KEY (`dispatch_id`) REFERENCES `sls_dispatch` (`dispatch_id`),
    CONSTRAINT `fk_ditem_wo` FOREIGN KEY (`wo_id`) REFERENCES `mfg_work_order` (`wo_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Состав отгрузок (какая партия, сколько)';

CREATE TABLE `sls_claim` (
    `claim_id` INT UNSIGNED NOT NULL,
    `claim_no` VARCHAR(16) NOT NULL,
    `contract_id` INT UNSIGNED NOT NULL,
    `dispatch_id` INT UNSIGNED NULL,
    `product_id` SMALLINT UNSIGNED NOT NULL,
    `opened_on` DATE NOT NULL,
    `closed_on` DATE NULL,
    `claim_type` ENUM('transport_damage','manufacturing_defect','wrong_spec','shortage','late_delivery') NOT NULL,
    `qty_affected` DECIMAL(12,2) NOT NULL,
    `credit_amount_tjs` DECIMAL(12,2) NOT NULL,
    `resolution` ENUM('replacement','credit_note','repair','rejected','pending') NOT NULL,
    `claim_status` ENUM('open','closed') NOT NULL,
    PRIMARY KEY (`claim_id`),
    UNIQUE KEY `uq_claim_no` (`claim_no`),
    KEY `ix_claim_contract` (`contract_id`),
    CONSTRAINT `fk_claim_contract` FOREIGN KEY (`contract_id`) REFERENCES `sls_contract` (`contract_id`),
    CONSTRAINT `fk_claim_dispatch` FOREIGN KEY (`dispatch_id`) REFERENCES `sls_dispatch` (`dispatch_id`),
    CONSTRAINT `fk_claim_product` FOREIGN KEY (`product_id`) REFERENCES `cat_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Рекламации клиентов';

CREATE TABLE `qa_ncr` (
    `ncr_id` INT UNSIGNED NOT NULL,
    `ncr_no` VARCHAR(16) NOT NULL,
    `source` ENUM('incoming','in_process','final','customer') NOT NULL,
    `wo_id` INT UNSIGNED NULL,
    `receipt_id` INT UNSIGNED NULL,
    `claim_id` INT UNSIGNED NULL,
    `raised_on` DATE NOT NULL,
    `closed_on` DATE NULL,
    `severity` ENUM('minor','major','critical') NOT NULL,
    `defect_code` VARCHAR(24) NOT NULL,
    `description` VARCHAR(255) NOT NULL,
    `disposition` ENUM('rework','scrap','use_as_is','return_to_vendor','pending') NOT NULL,
    `cost_tjs` DECIMAL(12,2) NOT NULL,
    `raised_by_id` SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`ncr_id`),
    UNIQUE KEY `uq_ncr_no` (`ncr_no`),
    KEY `ix_ncr_raised` (`raised_on`),
    CONSTRAINT `fk_ncr_wo` FOREIGN KEY (`wo_id`) REFERENCES `mfg_work_order` (`wo_id`),
    CONSTRAINT `fk_ncr_receipt` FOREIGN KEY (`receipt_id`) REFERENCES `scm_receipt` (`receipt_id`),
    CONSTRAINT `fk_ncr_claim` FOREIGN KEY (`claim_id`) REFERENCES `sls_claim` (`claim_id`),
    CONSTRAINT `fk_ncr_by` FOREIGN KEY (`raised_by_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Отчёты о несоответствиях (NCR)';

CREATE TABLE `mfg_downtime` (
    `downtime_id` INT UNSIGNED NOT NULL,
    `wc_id` TINYINT UNSIGNED NOT NULL,
    `started_at` DATETIME NOT NULL,
    `duration_min` INT UNSIGNED NOT NULL,
    `downtime_category` ENUM('breakdown','changeover','no_material','power_outage','no_orders','planned_maintenance','quality_hold') NOT NULL,
    `is_planned` TINYINT(1) NOT NULL,
    `description` VARCHAR(160) NOT NULL,
    `reported_by_id` SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`downtime_id`),
    KEY `ix_down_wc` (`wc_id`, `started_at`),
    CONSTRAINT `fk_down_wc` FOREIGN KEY (`wc_id`) REFERENCES `mfg_workcenter` (`wc_id`),
    CONSTRAINT `fk_down_by` FOREIGN KEY (`reported_by_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Простои оборудования';

CREATE TABLE `mfg_maintenance` (
    `mo_id` INT UNSIGNED NOT NULL,
    `mo_no` VARCHAR(12) NOT NULL,
    `wc_id` TINYINT UNSIGNED NOT NULL,
    `mo_type` ENUM('preventive','corrective','calibration') NOT NULL,
    `opened_on` DATE NOT NULL,
    `closed_on` DATE NULL,
    `downtime_id` INT UNSIGNED NULL,
    `labor_hours` DECIMAL(6,1) NOT NULL,
    `parts_cost_tjs` DECIMAL(12,2) NOT NULL,
    `technician_id` SMALLINT UNSIGNED NOT NULL,
    `mo_description` VARCHAR(160) NOT NULL,
    PRIMARY KEY (`mo_id`),
    UNIQUE KEY `uq_mo_no` (`mo_no`),
    KEY `ix_mo_wc` (`wc_id`),
    CONSTRAINT `fk_mo_wc` FOREIGN KEY (`wc_id`) REFERENCES `mfg_workcenter` (`wc_id`),
    CONSTRAINT `fk_mo_downtime` FOREIGN KEY (`downtime_id`) REFERENCES `mfg_downtime` (`downtime_id`),
    CONSTRAINT `fk_mo_tech` FOREIGN KEY (`technician_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Заказы на техобслуживание и ремонт';

CREATE TABLE `ops_energy_reading` (
    `reading_date` DATE NOT NULL,
    `site_id` TINYINT UNSIGNED NOT NULL,
    `meter` ENUM('electricity_kwh','water_m3','diesel_l') NOT NULL,
    `reading_value` DECIMAL(12,1) NOT NULL,
    `cost_tjs` DECIMAL(12,2) NOT NULL,
    PRIMARY KEY (`reading_date`, `site_id`, `meter`),
    KEY `ix_energy_site` (`site_id`),
    CONSTRAINT `fk_energy_site` FOREIGN KEY (`site_id`) REFERENCES `core_site` (`site_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Суточный расход энергоресурсов по площадкам';

CREATE TABLE `hse_incident` (
    `incident_id` INT UNSIGNED NOT NULL,
    `incident_at` DATETIME NOT NULL,
    `site_id` TINYINT UNSIGNED NOT NULL,
    `wc_id` TINYINT UNSIGNED NULL,
    `incident_type` ENUM('near_miss','first_aid','lost_time','chemical_spill','fire_alarm') NOT NULL,
    `severity` ENUM('low','medium','high') NOT NULL,
    `emp_id` SMALLINT UNSIGNED NULL,
    `lost_days` SMALLINT UNSIGNED NOT NULL,
    `incident_desc` VARCHAR(200) NOT NULL,
    `corrective_action_done` TINYINT(1) NOT NULL,
    PRIMARY KEY (`incident_id`),
    KEY `ix_hse_at` (`incident_at`),
    CONSTRAINT `fk_hse_site` FOREIGN KEY (`site_id`) REFERENCES `core_site` (`site_id`),
    CONSTRAINT `fk_hse_wc` FOREIGN KEY (`wc_id`) REFERENCES `mfg_workcenter` (`wc_id`),
    CONSTRAINT `fk_hse_emp` FOREIGN KEY (`emp_id`) REFERENCES `hr_employee` (`emp_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Инциденты охраны труда и экологии';

CREATE TABLE `fin_expense` (
    `expense_id` INT UNSIGNED NOT NULL,
    `expense_date` DATE NOT NULL,
    `cc_id` TINYINT UNSIGNED NOT NULL,
    `expense_category` ENUM('payroll','utilities','rent','logistics','maintenance_parts','marketing','travel','insurance','taxes_fees','professional_services','depreciation','it_telecom') NOT NULL,
    `description` VARCHAR(160) NOT NULL,
    `amount_tjs` DECIMAL(14,2) NOT NULL,
    `vendor_id` SMALLINT UNSIGNED NULL,
    `doc_no` VARCHAR(16) NOT NULL,
    PRIMARY KEY (`expense_id`),
    KEY `ix_expense_date` (`expense_date`),
    KEY `ix_expense_cc` (`cc_id`),
    CONSTRAINT `fk_expense_cc` FOREIGN KEY (`cc_id`) REFERENCES `fin_cost_center` (`cc_id`),
    CONSTRAINT `fk_expense_vendor` FOREIGN KEY (`vendor_id`) REFERENCES `scm_vendor` (`vendor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Операционные расходы (без сырья)';

CREATE TABLE `fin_budget` (
    `period_month` DATE NOT NULL,
    `cc_id` TINYINT UNSIGNED NOT NULL,
    `expense_category` ENUM('payroll','utilities','rent','logistics','maintenance_parts','marketing','travel','insurance','taxes_fees','professional_services','depreciation','it_telecom') NOT NULL,
    `budget_amount_tjs` DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (`period_month`, `cc_id`, `expense_category`),
    CONSTRAINT `fk_budget_cc` FOREIGN KEY (`cc_id`) REFERENCES `fin_cost_center` (`cc_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Бюджет расходов по месяцам';

CREATE TABLE `fin_sales_plan` (
    `period_month` DATE NOT NULL,
    `family_id` TINYINT UNSIGNED NOT NULL,
    `plan_revenue_tjs` DECIMAL(14,2) NOT NULL,
    `plan_volume_kg` DECIMAL(14,1) NOT NULL,
    PRIMARY KEY (`period_month`, `family_id`),
    CONSTRAINT `fk_plan_family` FOREIGN KEY (`family_id`) REFERENCES `cat_family` (`family_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='План продаж по семействам продукции';






















































































































































































































































































































































































































































