INSERT INTO `cat_family` (`family_id`, `family_code`, `family_name`, `market_segment`, `typical_lead_days`, `description`) VALUES
(1, 'REB', 'Композитная арматура', 'construction', 14, 'Стеклопластиковая арматура периодического профиля для бетонных, дорожных и мостовых конструкций'),
(2, 'PIP', 'Трубы и фитинги', 'infrastructure', 30, 'Стеклопластиковые трубы намоточные SN5000 и фасонные части для водоснабжения, канализации, ирригации'),
(3, 'PRF', 'Конструкционные профили', 'industrial', 21, 'Пултрузионные профили: двутавры, швеллеры, уголки, трубы и пластины'),
(4, 'GRT', 'Настилы, лотки и лестницы', 'industrial', 25, 'Решётчатые настилы, кабельные лотки и лестницы для агрессивных сред и энергетики'),
(5, 'TNK', 'Ёмкости и резервуары', 'chemicals', 35, 'Ёмкости для воды, кислот, щелочей и пищевых жидкостей объёмом 1–50 м³'),
(6, 'PNL', 'Листы и панели', 'construction', 28, 'Светопрозрачные листы, фасадные сэндвич-панели, SMC-корпуса и люки'),
(7, 'AUT', 'Изделия для транспорта', 'transport', 45, 'Кузовные панели, обтекатели, бамперы, корпуса катеров и модули'),
(8, 'CMP', 'Композитные смеси и смолы', 'chemicals', 10, 'Премиксы SMC/BMC, полимербетон, гелькоут, смолы и инфузионные системы собственного производства');
